class WeatherCache {
  constructor(ttl = 300000) { // 5-minute default TTL
    this.cache = {};
    this.ttl = ttl;
  }

  get(city) {
    if (this.cache[city] && this.cache[city].expires > Date.now()) {
      return this.cache[city].data;
    }
    return null;
  }

  set(city, data) {
    this.cache[city] = {
      data,
      expires: Date.now() + this.ttl
    };
  }
}
